// Halaman form klaim (di-serve langsung oleh n8n)
const POLICY = `Company reimbursement policy: meals up to 150000 IDR, transport up to 100000 IDR, office supplies up to 300000 IDR, anything else up to 100000 IDR. Reject receipts older than 30 days or dated in the future. Reject receipts where total, merchant or date cannot be read. Reject alcohol. Only IDR receipts are accepted.`;
const html = `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>ReimburseAI</title>
<style>
body{font-family:system-ui,-apple-system,sans-serif;background:#0d1117;color:#e6edf3;margin:0;padding:28px;display:flex;justify-content:center}
.card{background:#161b22;border:1px solid #30363d;border-radius:14px;padding:28px;max-width:640px;width:100%}
h1{font-size:22px;margin:0 0 4px}.muted{color:#8b949e;font-size:13px}
label{display:block;margin:18px 0 6px;font-size:13px;color:#8b949e}
input{width:100%;padding:10px 12px;border-radius:8px;border:1px solid #30363d;background:#0d1117;color:#e6edf3;font-size:14px;box-sizing:border-box}
input[type=file]{border-style:dashed;color:#8b949e;font-size:13px}
button{margin-top:20px;width:100%;padding:12px;border:0;border-radius:8px;background:#238636;color:#fff;font-size:15px;font-weight:600;cursor:pointer}
button:disabled{opacity:.5}
.policy{margin-top:22px;padding:12px;border-radius:8px;background:#0d1117;border:1px solid #21262d;font-size:12px;color:#8b949e;line-height:1.5}
pre{white-space:pre-wrap;font-size:12px;color:#c9d1d9}
#out{margin-top:22px;display:none}
</style></head><body><div class="card">
<h1>ReimburseAI</h1><span class="muted">Snap a receipt, get reimbursed to PayPal</span>
<form id="f">
  <label>Employee PayPal email (sandbox)</label>
  <input type="email" id="email" required placeholder="sb-xxxx@personal.example.com">
  <label>Receipt photo</label>
  <input type="file" id="file" accept="image/*" required>
  <button id="go" type="submit">Submit claim</button>
</form>
<div class="policy"><b>Company policy</b><br>${POLICY}</div>
<div id="out"><h1 id="title" style="margin-top:0"></h1><pre id="body"></pre></div>
</div>
<script>
const ENDPOINT='https://bengss.app.n8n.cloud/webhook/reimburse';
const f=document.getElementById('f'),go=document.getElementById('go'),out=document.getElementById('out'),
 t=document.getElementById('title'),b=document.getElementById('body');
f.addEventListener('submit',async(e)=>{
  e.preventDefault(); go.disabled=true; go.textContent='Processing...';
  const file=document.getElementById('file').files[0];
  const b64=await new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(String(fr.result).split(',')[1]);fr.readAsDataURL(file)});
  try{
    const res=await fetch(ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({image:'data:'+(file.type||'image/jpeg')+';base64,'+b64,
        employee_email:document.getElementById('email').value})});
    const txt=await res.text();
    const appr=txt.match(/https:\/\/[^"'\s]+reimburse-approve[^"'\s]*/);
    t.textContent=appr?'Claim passed AI policy check':'Claim rejected';
    b.textContent=appr?('Claim created. Open the manager approval page to release the payout.'):txt.slice(0,400);
    if(appr){const a=document.createElement('a');a.href=appr[0];a.textContent='Open manager approval page';
      a.style.cssText='color:#58a6ff;display:inline-block;margin-top:10px';b.appendChild(document.createElement('br'));b.appendChild(a);}
  }catch(err){t.textContent='Request failed';b.textContent=String(err);}
  out.style.display='block';go.disabled=false;go.textContent='Submit another claim';
});
</script></div></body></html>`;
return [{ json: { status: 200, html } }];

// Normalisasi klaim + siapkan request AI
const inp = $input.first().json;
const body = inp.body ?? inp;
if (!body.image) throw new Error('Field "image" wajib diisi');
if (!body.employee_email) throw new Error('Field "employee_email" wajib diisi');
let image = String(body.image);
if (!/^https?:\/\//i.test(image) && !image.startsWith('data:')) {
  image = 'data:image/jpeg;base64,' + image.replace(/\s/g, '');
}
const POLICY = `Company reimbursement policy: meals up to 150000 IDR, transport up to 100000 IDR, office supplies up to 300000 IDR, anything else up to 100000 IDR. Reject receipts older than 30 days or dated in the future. Reject receipts where total, merchant or date cannot be read. Reject alcohol. Only IDR receipts are accepted.`;
return [{ json: {
  employee_email: String(body.employee_email).trim().toLowerCase(),
  image,
  aiBody: {
    model: 'deepseek-flash',
    temperature: 0,
    max_tokens: 1200,
    messages: [
      { role: 'system', content: 'You read expense receipts and apply a company policy. Reply with ONLY JSON: {"merchant":string|null,"date":"YYYY-MM-DD"|null,"total":number|null,"currency":"IDR"|null,"category":"meal|transport|supplies|other","items":[{"name":"","amount":0}],"policy_verdict":"approve"|"reject","policy_reasons":[string]}. Numbers have no thousand separators.' },
      { role: 'user', content: [
        { type: 'image_url', image_url: { url: image } },
        { type: 'text', text: 'TODAY: ' + new Date().toISOString().slice(0,10) + '\nPOLICY: ' + POLICY + '\n\nJudge every date relative to TODAY. Read the receipt, then decide policy_verdict and explain briefly in policy_reasons. Categories: meal, transport, supplies, other.' }
      ] }
    ]
  }
} }];

// Keputusan akhir: AI + pengaman keras di kode + deteksi duplikat
const ai = $input.first().json;
const src = $('Normalize Claim').first().json;

const raw = (ai.choices && ai.choices[0] && ai.choices[0].message && ai.choices[0].message.content) || '';
let doc = null;
try { doc = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { doc = JSON.parse(m[0]); } catch (e2) { doc = null; } }
}
if (!doc) throw new Error('AI tidak mengembalikan JSON yang valid');

const LIMITS_IDR = { meal: 150000, transport: 100000, supplies: 300000, other: 100000 };
const MAX_AGE_DAYS = 30;
const IDR_PER_USD = 16000;
const CATS = ['meal', 'transport', 'supplies', 'other'];

const total = Number(doc.total);
const category = CATS.includes(String(doc.category)) ? String(doc.category) : 'other';
const merchant = doc.merchant ? String(doc.merchant) : null;
const date = /^\d{4}-\d{2}-\d{2}$/.test(String(doc.date)) ? String(doc.date) : null;
const currency = String(doc.currency || '').toUpperCase();
const limit = LIMITS_IDR[category];

const aiNotes = Array.isArray(doc.policy_reasons) ? doc.policy_reasons.map(String).slice(0, 6) : [];
const reasons = [];
if (doc.policy_verdict !== 'approve') {
  if (aiNotes.length) reasons.push(...aiNotes);
  else reasons.push('AI policy check did not approve this receipt');
}

// pengaman keras: AI bukan satu-satunya penjaga uang
if (!Number.isFinite(total) || total <= 0) reasons.push('receipt total could not be read');
if (currency && currency !== 'IDR') reasons.push('currency ' + currency + ' is not allowed');
if (!date) reasons.push('receipt date could not be read');
if (!merchant) reasons.push('merchant name could not be read');
if (Number.isFinite(total) && total > limit) reasons.push('exceeds the ' + category + ' limit of Rp ' + limit.toLocaleString('id-ID'));
if (date) {
  const age = Math.floor((Date.now() - new Date(date + 'T00:00:00Z').getTime()) / 86400000);
  if (age > MAX_AGE_DAYS) reasons.push('receipt is older than ' + MAX_AGE_DAYS + ' days');
  if (age < -1) reasons.push('receipt date is in the future');
}

const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const hash = [merchant || '?', date || '?', Number.isFinite(total) ? total : '?', src.employee_email].join('|').toLowerCase();
if (sd.seen[hash]) reasons.push('this receipt was already submitted');

const unique = Array.from(new Set(reasons));
const approved = unique.length === 0;
const ref = Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
const token = Math.random().toString(36).slice(2, 10);

const claim = {
  ref, token, approved,
  reasons: unique,
  ai_notes: aiNotes,
  merchant, date, category,
  total_idr: Number.isFinite(total) ? total : null,
  amount_usd: approved ? (Math.round((total / IDR_PER_USD) * 100) / 100).toFixed(2) : null,
  currency_in: currency || null,
  limit_idr: limit,
  employee_email: src.employee_email,
  items: Array.isArray(doc.items) ? doc.items.slice(0, 20) : [],
  status: approved ? 'pending_approval' : 'rejected',
  hash
};

if (approved) {
  sd.seen[hash] = ref;
  sd.claims = sd.claims || {};
  sd.claims[ref] = claim;
}
return [{ json: claim }];

// Halaman penolakan klaim
const d = $input.first().json;
const money = n => (n === null || n === undefined) ? '-' : 'Rp ' + Number(n).toLocaleString('id-ID');
const items = (d.reasons || []).map(r => '<li>' + r + '</li>').join('');
const html = '<!doctype html><html><head><meta charset="utf-8"><title>ReimburseAI</title>'
 + '<style>body{font-family:system-ui,sans-serif;background:#0d1117;color:#e6edf3;margin:0;padding:28px;display:flex;justify-content:center}'
 + '.card{background:#161b22;border:1px solid #30363d;border-radius:14px;padding:28px;max-width:620px;width:100%}'
 + 'h1{font-size:22px;margin:0 0 4px}.bad{color:#f85149}.muted{color:#8b949e;font-size:13px}'
 + 'dl{display:grid;grid-template-columns:auto 1fr;gap:10px 18px;margin:22px 0;font-size:14px}'
 + 'dt{color:#8b949e}dd{margin:0;text-align:right}ul{color:#f85149;font-size:14px;line-height:1.6}'
 + '.badge{display:inline-block;background:#3a1416;color:#f85149;border-radius:999px;padding:2px 10px;font-size:12px;margin-left:8px}'
 + '</style></head><body><div class="card"><h1 class="bad">Claim rejected<span class="badge">NO PAYOUT</span></h1>'
 + '<span class="muted">ReimburseAI &middot; claim ' + d.ref + '</span>'
 + '<dl><dt>Merchant</dt><dd>' + (d.merchant || '-') + '</dd>'
 + '<dt>Date</dt><dd>' + (d.date || '-') + '</dd>'
 + '<dt>Total</dt><dd>' + money(d.total_idr) + '</dd>'
 + '<dt>Limit</dt><dd>' + money(d.limit_idr) + '</dd></dl>'
 + '<ul>' + items + '</ul></div></body></html>';
return [{ json: { status: 200, html } }];

// Ambil klaim (ref + token) — tanpa throw, supaya bisa tampil halaman ramah
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
const claim = (sd.claims || {})[q.ref];
if (!claim) return [{ json: { ok: false, reason: 'not_found', ref: q.ref || null } }];
if (String(claim.token) !== String(q.token)) return [{ json: { ok: false, reason: 'bad_token', ref: q.ref || null } }];
if (claim.status === 'paid') return [{ json: Object.assign({}, claim, { ok: false, reason: 'already_paid' }) }];
return [{ json: Object.assign({}, claim, { ok: true }) }];

// Ambil klaim (ref + token) — tanpa throw, supaya bisa tampil halaman ramah
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
const claim = (sd.claims || {})[q.ref];
if (!claim) return [{ json: { ok: false, reason: 'not_found', ref: q.ref || null } }];
if (String(claim.token) !== String(q.token)) return [{ json: { ok: false, reason: 'bad_token', ref: q.ref || null } }];
if (claim.status === 'paid') return [{ json: Object.assign({}, claim, { ok: false, reason: 'already_paid' }) }];
return [{ json: Object.assign({}, claim, { ok: true }) }];

// Tandai klaim sudah dibayar
const payout = $input.first().json || {};
const claim = $('Load Claim Pay').first().json;
const sd = $getWorkflowStaticData('global');
if (sd.claims && sd.claims[claim.ref]) {
  sd.claims[claim.ref].status = 'paid';
  sd.claims[claim.ref].payout_batch_id = (payout.batch_header && payout.batch_header.payout_batch_id) || null;
}
return [{ json: Object.assign({}, claim, {
  approved: true,
  status: 'paid',
  payout_batch_id: (payout.batch_header && payout.batch_header.payout_batch_id) || null,
  payout_status: (payout.batch_header && payout.batch_header.batch_status) || null
}) }];

// Human-facing info page: reused link / claim already paid (light theme, plain English)
const d = $input.first().json;
const MAP = {
  already_paid: ['This claim has already been paid', 'The payout for this claim was already sent to PayPal. No second payment was created.', 'No new payment', '#1a7f37', '#e6f4ea'],
  not_found:    ['Claim not found', 'This link has expired, or the claim data was reset when the workflow was re-imported.', 'Link expired', '#9a6700', '#fff8c5'],
  bad_token:    ['Invalid link', 'The token in this link does not match this claim.', 'Access denied', '#b42318', '#fdecea']
};
const m = MAP[d.reason] || ['This link cannot be used', 'This claim can no longer be processed.', 'Info', '#9a6700', '#fff8c5'];
const title = m[0], desc = m[1], badge = m[2], fg = m[3], bg = m[4];
const money = n => (n === null || n === undefined || n === '') ? '-' : 'Rp ' + Number(n).toLocaleString('en-US');
const usd = n => (n === null || n === undefined || n === '') ? '-' : Number(n).toFixed(2) + ' USD';
const rows = [];
rows.push(['Reference', d.ref ? String(d.ref) : '-']);
if (d.merchant) rows.push(['Merchant', String(d.merchant)]);
if (d.date) rows.push(['Date', String(d.date)]);
if (d.total_idr !== null && d.total_idr !== undefined) rows.push(['Receipt total', money(d.total_idr)]);
if (d.amount_usd) rows.push(['Payout', usd(d.amount_usd)]);
if (d.employee_email) rows.push(['Recipient', String(d.employee_email)]);
if (d.payout_batch_id) rows.push(['PayPal batch', String(d.payout_batch_id)]);
const status = d.reason === 'already_paid' ? 409 : 404;
const dl = rows.map(r => '<div class="row"><dt>' + r[0] + '</dt><dd>' + r[1] + '</dd></div>').join('');
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8">'
 + '<meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + '</title>'
 + '<style>'
 + '*{box-sizing:border-box}'
 + 'body{font-family:ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f4f2ec;color:#1f2328;margin:0;padding:32px 18px;display:flex;justify-content:center;align-items:flex-start;min-height:100vh}'
