 + '.badge{display:inline-block;font-size:12px;font-weight:600;color:' + fg + ';background:' + bg + ';border-radius:999px;padding:5px 12px;margin-bottom:16px}'
 + 'h1{font-size:23px;line-height:1.25;margin:0 0 8px;font-weight:650}'
 + '.muted{color:#5c6370;font-size:14px;line-height:1.6;margin:0 0 22px}'
