 + 'dt{color:#6b7280;margin:0}dd{margin:0;font-weight:550;word-break:break-word}'
 + '.foot{margin-top:22px}'
 + 'a.btn{display:inline-block;text-decoration:none;font-size:14px;font-weight:600;padding:10px 16px;border-radius:10px;background:#1f2328;color:#fff}'
 + '</style></head><body><div class="card">'
 + '<span class="badge">' + badge + '</span>'
 + '<h1>' + title + '</h1>'
 + '<p class="muted">' + desc + '</p>'
 + '<dl>' + dl + '</dl>'
 + '<div class="foot"><a class="btn" href="/webhook/reimburse-form">Submit a new claim</a></div>'
 + '</div></body></html>';
return [{ json: { html, status } }];

