const d = $input.first().json;
const MAP = {
  already_paid: ['This claim has already been paid', 'The payout for this claim was already sent to PayPal. No second payment was created.', 'No new payment', '#1a7f37', '#e6f4ea'],
  not_found:    ['Claim not found', 'This link has expired, or the claim data was reset when the workflow was re-imported.', 'Link expired', '#9a6700', '#fff8c5'],
